{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Can I fly a Cessna 172 on Sport Pilot medical?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Do not decide this from the former Light-Sport Aircraft definition. Since MOSAIC, Sport Pilot eligibility depends on the current §61.316 criteria and any required endorsements. Confirm the exact model and configuration with an instructor before planning a flight."
      }
    },
    {
      "@type": "Question",
      "name": "Does Sport Pilot count toward Private Pilot hours later?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Solo and dual hours logged as a Sport Pilot student or Sport Pilot count toward the Private Pilot 40-hour minimum."
      }
    },
    {
      "@type": "Question",
      "name": "If I have BasicMed, can I rent aircraft from flight schools?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Generally yes, if the aircraft is within current BasicMed limits (up to 12,500 pounds and seven authorized occupants, subject to the rule’s conditions) and the school accepts BasicMed for rentals. Policies vary by school."
      }
    },
    {
      "@type": "Question",
      "name": "Is BasicMed recognized in Canada or Mexico?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "BasicMed can be used outside the United States only where the destination country authorizes it. Check the destination’s current rules before flight."
      }
    },
    {
      "@type": "Question",
      "name": "What if my AME defers me?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Deferral means the FAA — not the AME — makes the call. It's not denial. The FAA may request additional records or tests. Timing depends on the case; work with your AME on the next steps."
      }
    }
  ]
}

