{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Where is the FAA testing center in Louisville?",
      "acceptedAnswer": { "@type": "Answer", "text": "FAA knowledge tests are given at PSI testing centers, and PSI operates locations serving the Louisville area. Addresses and hours change, so use the test-center search at faa.psiexams.com when you schedule." }
    },
    {
      "@type": "Question",
      "name": "How much does the FAA written test cost?",
      "acceptedAnswer": { "@type": "Answer", "text": "Most FAA airman knowledge tests have been running around $175. Fees change, so confirm the current amount at psiexams.com when you schedule. A retake costs the full fee again." }
    },
    {
      "@type": "Question",
      "name": "Do I need an endorsement to take the FAA written test?",
      "acceptedAnswer": { "@type": "Answer", "text": "Yes for the Private Pilot test and most others — 14 CFR 61.35 requires an authorized instructor's endorsement certifying you are prepared. A flight instructor (CFI) or an Advanced Ground Instructor (AGI) can provide it." }
    },
    {
      "@type": "Question",
      "name": "Can I take the FAA written test before I start flying?",
      "acceptedAnswer": { "@type": "Answer", "text": "Yes. An AGI can sign your endorsement without you being enrolled in flight training, and the knowledge test report is valid for 24 calendar months." }
    },
    {
      "@type": "Question",
      "name": "What happens if I fail the FAA written test?",
      "acceptedAnswer": { "@type": "Answer", "text": "You will need additional training on the deficient areas and a new endorsement before retesting (14 CFR 61.49), plus the test fee again. The test report's ACS codes identify which subject areas to fix." }
    }
  ]
}

