{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many flight schools are there in the Louisville area?",
      "acceptedAnswer": { "@type": "Answer", "text": "A handful of training providers operate out of Bowman Field (KLOU) in Louisville, plus options at Clark Regional (KJVY) in Jeffersonville and independent CFIs. The exact lineup changes, so verify who is currently operating before building a shortlist." }
    },
    {
      "@type": "Question",
      "name": "Is a Part 141 school better than Part 61 for a hobby pilot?",
      "acceptedAnswer": { "@type": "Answer", "text": "Usually not. Part 141 structure is built for full-time and career-track students. A recreational student flying around a work schedule is typically better served by the flexibility of Part 61, either at a local Part 61 school or with an independent instructor." }
    },
    {
      "@type": "Question",
      "name": "Should I pay for a big block of flight time up front?",
      "acceptedAnswer": { "@type": "Answer", "text": "Be cautious. Pay-as-you-go is standard in the Louisville Part 61 market and keeps risk on the provider's side. If a school wants a large non-refundable prepayment, get the refund policy in writing first." }
    },
    {
      "@type": "Question",
      "name": "Can I switch instructors or schools mid-training?",
      "acceptedAnswer": { "@type": "Answer", "text": "Yes. Your logbook and training records are yours. A new instructor will review what has been done, verify it is solid, and continue from there." }
    },
    {
      "@type": "Question",
      "name": "What is the single best way to evaluate a flight school?",
      "acceptedAnswer": { "@type": "Answer", "text": "Book a discovery flight. One hour in the left seat tells you more about the operation, the instructor, and whether flying is for you than any website or tour." }
    }
  ]
}

