{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is there really a TFR over Churchill Downs during the Kentucky Derby?",
      "acceptedAnswer": { "@type": "Answer", "text": "Yes. The FAA establishes temporary flight restrictions over Churchill Downs around the major race days each year. Exact radius, altitude, and active times are published in NOTAMs annually and change — check the current NOTAM." }
    },
    {
      "@type": "Question",
      "name": "Can student pilots fly out of Bowman Field during Derby week?",
      "acceptedAnswer": { "@type": "Answer", "text": "Often yes, but not always — it depends on the TFR windows and event procedures in effect that day. Check NOTAMs and ATIS before every flight that week and coordinate with your instructor." }
    },
    {
      "@type": "Question",
      "name": "What airports do the Kentucky Derby special procedures cover?",
      "acceptedAnswer": { "@type": "Answer", "text": "The FAA's annual Derby procedures notice covers Louisville Muhammad Ali International (KSDF), Bowman Field (KLOU), and Clark Regional (KJVY). Read the current year's notice for actual requirements." }
    },
    {
      "@type": "Question",
      "name": "Does Thunder Over Louisville affect flying too?",
      "acceptedAnswer": { "@type": "Answer", "text": "Yes. Thunder Over Louisville brings its own temporary restrictions along the Ohio River, plus a rehearsal day. Treat the whole festival stretch as mandatory-NOTAM-check territory." }
    },
    {
      "@type": "Question",
      "name": "What happens if you accidentally fly into a TFR?",
      "acceptedAnswer": { "@type": "Answer", "text": "Expect anything from an FAA investigation and certificate action to, during a major security event, interception by military or law enforcement aircraft. Checking NOTAMs before every flight is non-negotiable." }
    }
  ]
}

