{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What runways does Bowman Field have?",
      "acceptedAnswer": { "@type": "Answer", "text": "Two intersecting asphalt runways: 06/24 at 4,358 x 75 feet and 15/33 at 3,580 x 75 feet. Both have published displaced-threshold and declared-distance information. Confirm current data in the Chart Supplement before flying." }
    },
    {
      "@type": "Question",
      "name": "What is the traffic pattern altitude at Bowman Field?",
      "acceptedAnswer": { "@type": "Answer", "text": "No nonstandard pattern altitude is published for KLOU, so the FAA standard 1,000 feet AGL applies — about 1,550 feet MSL at the 546-foot field elevation, keeping the pattern under the nearby Class C shelf. Tower instructions control if different." }
    },
    {
      "@type": "Question",
      "name": "Can you do pattern work at Bowman Field when the tower is closed?",
      "acceptedAnswer": { "@type": "Answer", "text": "Published FAA remarks restrict training operations at KLOU when the tower is closed, so confirm the current Chart Supplement remarks and NOTAMs before planning off-hours pattern sessions. The tower operates roughly 0700-2200 local." }
    },
    {
      "@type": "Question",
      "name": "How many landings does it take to get consistent?",
      "acceptedAnswer": { "@type": "Answer", "text": "There is no honest fixed number. Consistency comes faster with purposeful laps, consistent lesson cadence, and real debriefs — one correction at a time — rather than chasing a total count." }
    },
    {
      "@type": "Question",
      "name": "When should a student pilot go around?",
      "acceptedAnswer": { "@type": "Answer", "text": "Any time the approach is not stabilized by the agreed gate on short final — speed, path, configuration, or alignment off — and any time Tower instructs it. A go-around is a normal, professional maneuver." }
    }
  ]
}

