  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long is a MedXPress application valid after I submit?",
      "acceptedAnswer": { "@type": "Answer", "text": "60 days. Fill it out a few days before your AME appointment — not the same morning in a rush, and not months ahead." }
    },
    {
      "@type": "Question",
      "name": "What class of medical should a student pilot apply for?",
      "acceptedAnswer": { "@type": "Answer", "text": "Third Class covers Private Pilot privileges and is the standard choice for new students. If the Sport Pilot path or BasicMed fits your goals, you may not need an FAA medical exam at all — decide before booking the AME." }
    },
    {
      "@type": "Question",
      "name": "Will a yes answer on the FAA medical history disqualify me?",
      "acceptedAnswer": { "@type": "Answer", "text": "Usually not automatically. Many yes answers lead to documentation requests or a deferral rather than a denial, and many of those still end in issuance. Falsifying the form is far worse than any disclosed condition." }
    },
    {
      "@type": "Question",
      "name": "How much does the FAA medical exam cost in Louisville?",
      "acceptedAnswer": { "@type": "Answer", "text": "Fees vary by examiner; roughly $100–$200 is a realistic local range for a Third Class exam, sometimes more for first-time applicants. Confirm the fee when you book." }
    },
    {
      "@type": "Question",
      "name": "What happens if my FAA medical application gets deferred?",
      "acceptedAnswer": { "@type": "Answer", "text": "The AME forwards your file to the FAA's Aerospace Medical Certification Division for review. Expect requests for records or additional testing, and expect months. Deferral is not denial — many deferred applicants are eventually issued." }
    }
  ]
}

